create table if not exists public.equipment (id integer generated by default as identity primary key, name varchar(80) not null unique, type varchar(80) not null, site varchar(80) not null, status varchar(16) not null default 'unknown' check (status in ('online','offline','unknown')), monitor_host varchar(255), monitoring_enabled boolean not null default false, last_checked_at timestamptz, response_ms integer check (response_ms is null or response_ms>=0), constraint equipment_monitor_host_required check (not monitoring_enabled or monitor_host is not null));
create table if not exists public.incidents (id integer generated by default as identity primary key, title varchar(120) not null, severity varchar(16) not null check (severity in ('low','medium','high','critical')), status varchar(16) not null check (status in ('open','in_progress','resolved')), equipment_id integer not null references public.equipment(id) on delete restrict);
create index if not exists ix_incidents_equipment_id on public.incidents(equipment_id);
create table if not exists public.directory_users (id integer generated by default as identity primary key, name varchar(100) not null, email varchar(160) not null unique, role varchar(16) not null check (role in ('admin','operator','viewer')));
create table if not exists public.monitoring_checks (id bigint generated always as identity primary key, equipment_id integer not null references public.equipment(id) on delete cascade, checked_at timestamptz not null default now(), status varchar(16) not null check (status in ('online','offline','unknown')), response_ms integer check (response_ms is null or response_ms>=0), error text);
create index if not exists ix_monitoring_checks_equipment_time on public.monitoring_checks(equipment_id, checked_at desc);
create table if not exists public.metrics (id bigint generated always as identity primary key, equipment_id integer not null references public.equipment(id) on delete cascade, recorded_at timestamptz not null default now(), cpu_percent numeric(5,2) check (cpu_percent between 0 and 100), ram_percent numeric(5,2) check (ram_percent between 0 and 100));
create index if not exists ix_metrics_equipment_time on public.metrics(equipment_id, recorded_at desc);
alter table public.equipment enable row level security;
alter table public.incidents enable row level security;
alter table public.directory_users enable row level security;
alter table public.monitoring_checks enable row level security;
alter table public.metrics enable row level security;
revoke all on public.equipment, public.incidents, public.directory_users, public.monitoring_checks, public.metrics from anon, authenticated;
